//! IWeb do SDK usa GetResponse no slot6 e entrega falha de rede por callback.
use std::path::PathBuf;
use zeebx::{brew::aee::{self,Interface},cpu::{BackendPadrao,CpuBackend,Reg},loader::{self,modfile::ModImage},machine::{Machine,Outcome},storage::StoragePaths};
struct F{m:Machine<BackendPadrao>,root:PathBuf,out:u32,pcb:u32,context:u32,url:u32,web:u32}
impl F{
 fn new()->Self{static NEXT:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);let root=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("local-tests/startup-repairs-wave21-20261031/wmapp").join(format!("web-test-{}-{}",std::process::id(),NEXT.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));std::fs::create_dir_all(&root).unwrap();let storage=StoragePaths::from_root(root.join("runtime"));storage.create_dirs().unwrap();let image=ModImage::parse([0xe3a00000u32,0xe12fff1e].into_iter().flat_map(u32::to_le_bytes).collect()).unwrap();let mut m=Machine::new_with_storage(BackendPadrao::new().unwrap(),loader::load_with(&image,&[]).unwrap(),&root,&storage,None);assert_eq!(m.run(1000).unwrap(),Outcome::Returned{code:0});m.set_network(false);let mut f=Self{m,root,out:loader::HEAP_BASE+0x4000,pcb:loader::HEAP_BASE+0x4040,context:loader::HEAP_BASE+0x4080,url:loader::HEAP_BASE+0x4100,web:0};f.api(Interface::Shell,"CreateInstance",[loader::OBJECT_BASE,0x01005000,f.out,0]);f.web=f.read(f.out);assert_ne!(f.web,0);f.m.cpu_mut().write_u32(f.out,0).unwrap();f.m.cpu_mut().write_mem(f.url,b"http://offline.invalid/update\0").unwrap();f.m.cpu_mut().write_mem(f.pcb,&[0;24]).unwrap();let cb=loader::MODULE_BASE+0x100;let code=[0xe92d4010u32,0xe1a04000,0xe5940004,0xe5900000,0xe5840008,0xe5901000,0xe5911018,0xe12fff31,0xe5900000,0xe584000c,0xe5940000,0xe2800001,0xe5840000,0xe8bd8010];f.m.cpu_mut().write_mem(cb,&code.into_iter().flat_map(u32::to_le_bytes).collect::<Vec<_>>()).unwrap();f.m.cpu_mut().write_u32(f.pcb+16,cb).unwrap();f.m.cpu_mut().write_u32(f.pcb+20,f.context).unwrap();f.m.cpu_mut().write_u32(f.context+4,f.out).unwrap();f}
 fn read(&self,p:u32)->u32{self.m.cpu().read_u32(p).unwrap()}
 fn entry(&mut self,e:u32,a:[u32;4])->u32{match self.m.call_guest(e,a,100000).unwrap(){Outcome::Returned{code}=>code,o=>panic!("{e:#x}: {o:?}")}}
 fn call(&mut self,obj:u32,slot:u32,a:[u32;3])->u32{let vt=self.read(obj);let e=self.read(vt+slot*4);self.entry(e,[obj,a[0],a[1],a[2]])}
 fn api(&mut self,i:Interface,n:&str,a:[u32;4])->u32{let slot=(0..256).find(|s|i.method(*s)==Some(n)).unwrap();self.entry(aee::encode(i,slot),a)}
 fn request(&mut self,slot:u32){let sp=self.m.cpu().read_reg(Reg::Sp);self.m.cpu_mut().write_u32(sp,0).unwrap();self.call(self.web,slot,[self.out,self.pcb,self.url]);}
 fn pending(&self)->Vec<(u32,u32)>{let s=self.m.grava_estado();zeebx::save_state::Leitor::abre(&s).unwrap().pares_em_ordem("agenda.callbacks").unwrap()}
 fn live(&self,p:u32)->bool{let s=self.m.grava_estado();zeebx::save_state::Leitor::abre(&s).unwrap().pares("objects.kinds").unwrap().iter().any(|(at,_)|*at==p)}
}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
#[test]fn sdk_getresponse_slot6_delivers_one_offline_response_after_return_and_survives_restore(){let mut f=F::new();f.request(6);assert_eq!(f.read(f.context),0,"a resposta deve esperar a volta do loop");assert_eq!(f.read(f.out),0);let pending=f.pending();assert_eq!(pending.len(),1,"GetResponse precisa agendar a resposta, não fingir AddOptBuffer");let state=f.m.grava_estado();f.m.restaura_estado(&state).unwrap();assert_eq!(f.m.deliver_signals(100000).unwrap().len(),1);assert_eq!(f.read(f.context),1);let response=f.read(f.out);assert_ne!(response,0);assert_eq!(f.read(f.context+8),response);assert_eq!(f.read(f.context+12),0xfffffdea,"nCode contém -AEE_NET_ENETDOWN, não um HTTP de servidor");let info=f.call(response,6,[0,0,0]);assert_eq!(f.read(info),0xfffffdea);assert_eq!(f.read(info+4),0);assert_eq!(f.read(info+8),u32::MAX);assert!(f.m.deliver_signals(100000).unwrap().is_empty());assert_eq!(f.call(f.web,1,[0,0,0]),0);assert!(f.live(response),"depois da notificação, a resposta pertence ao chamador");assert_eq!(f.call(response,1,[0,0,0]),0);assert!(!f.live(response));}
#[test]fn sdk_getresponsev_slot7_and_cancel_do_not_publish_or_leak_a_response(){let mut f=F::new();f.request(7);let queued=f.pending();assert_eq!(queued.len(),1);let response=queued[0].1;let cancel=f.read(f.pcb+8);assert_ne!(cancel,0);f.entry(cancel,[f.pcb,0,0,0]);assert!(f.m.deliver_signals(100000).unwrap().is_empty());assert_eq!(f.read(f.out),0);assert_eq!(f.read(f.context),0);assert!(!f.live(response));}
#[test]fn releasing_web_cancels_its_unpublished_response_and_callback(){let mut f=F::new();f.request(6);let queued=f.pending();assert_eq!(queued.len(),1);let response=queued[0].1;assert_eq!(f.call(f.web,1,[0,0,0]),0);assert!(f.m.deliver_signals(100000).unwrap().is_empty());assert_eq!(f.read(f.context),0);assert_eq!(f.read(f.out),0);assert!(!f.live(response));}
#[test]fn ixopts_slots_copy_strings_stack_values_and_remove_only_the_requested_entry(){let mut f=F::new();let opts=f.url+128;let text=f.url+256;f.m.cpu_mut().write_mem(text,b"original\0").unwrap();for(at,v)in[(opts,0x10005u32),(opts+4,text),(opts+8,0x20005),(opts+12,5000),(opts+16,0)]{f.m.cpu_mut().write_u32(at,v).unwrap();}assert_eq!(f.call(f.web,3,[opts,0,0]),0);f.m.cpu_mut().write_mem(text,b"changed!\0").unwrap();assert_eq!(f.call(f.web,5,[0x10005,0,f.out]),0);assert_eq!(f.read(f.out),0x10005);let value=f.read(f.out+4);assert_eq!(f.m.cpu().read_cstring(value,32),"original");f.m.cpu_mut().write_u32(opts,0x20005).unwrap();f.m.cpu_mut().write_u32(opts+4,9000).unwrap();f.m.cpu_mut().write_u32(opts+8,0).unwrap();assert_eq!(f.call(f.web,3,[opts,0,0]),0);assert_eq!(f.call(f.web,5,[0x20005,0,f.out]),0);assert_eq!(f.read(f.out+4),9000);assert_eq!(f.call(f.web,4,[0x20005,0,0]),0);assert_eq!(f.call(f.web,5,[0x20005,0,f.out]),0);assert_eq!(f.read(f.out+4),5000);assert_eq!(f.call(f.web,4,[0x20005,0,0]),0);assert_eq!(f.call(f.web,5,[0x20005,0,f.out]),1);}
#[test]fn reusing_the_callback_retires_the_previous_unpublished_response(){let mut f=F::new();f.request(6);let old=f.pending()[0].1;f.request(6);let pending=f.pending();assert_eq!(pending.len(),1);assert_ne!(pending[0].1,old);assert!(!f.live(old));assert_eq!(f.m.deliver_signals(100000).unwrap().len(),1);assert_eq!(f.read(f.context),1);let response=f.read(f.out);assert_eq!(f.call(response,1,[0,0,0]),0);}
#[test]fn option_capacity_is_total_across_add_calls_and_failure_keeps_existing_values(){let mut f=F::new();let base=f.url+512;for index in 0..128u32{f.m.cpu_mut().write_u32(base+index*8,0x20005).unwrap();f.m.cpu_mut().write_u32(base+index*8+4,index).unwrap();}f.m.cpu_mut().write_u32(base+128*8,0).unwrap();assert_eq!(f.call(f.web,3,[base,0,0]),0);for index in 0..128u32{f.m.cpu_mut().write_u32(base+index*8+4,index+128).unwrap();}assert_eq!(f.call(f.web,3,[base,0,0]),0);f.m.cpu_mut().write_u32(base+4,999).unwrap();f.m.cpu_mut().write_u32(base+8,0).unwrap();assert_eq!(f.call(f.web,3,[base,0,0]),2);assert_eq!(f.call(f.web,5,[0x20005,0,f.out]),0);assert_eq!(f.read(f.out+4),128);}
#[test]fn unsupported_https_reports_an_error_without_opening_a_socket(){let mut f=F::new();f.m.cpu_mut().write_mem(f.url,b"https://127.0.0.1:1/update\0").unwrap();f.m.set_network(true);f.request(6);assert_eq!(f.m.deliver_signals(100000).unwrap().len(),1);assert_eq!(f.read(f.context+12),(-0x505i32)as u32,"WEB_ERROR_UNSUPSCHEME não inventa TLS nem sucesso HTTP");let response=f.read(f.out);f.call(response,1,[0,0,0]);}

